/**
 * SQL builder (`/reports/sql`, key `reports_sql` plus an all-clients scope; customer feedback
 * 2026-11-04, docs/report-builder-plan.md §1.2). Report center, Recovery & team.
 *
 * Left: the data dictionary of the curated `bi` tables, every field with its type and an Arabic and
 * an English description, and the join keys. Main: a visual builder (table, joins, columns with
 * aggregates, filters, order, limit -> SQL generated by the API from its catalog) and a raw SQL
 * editor (Ctrl+Enter runs). Queries run on the read-only login (one SELECT, time and row limits);
 * results show in a grid with Excel export. Saved queries and the run history are below.
 * Every run is audited on the server.
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import classNames from 'classnames'
import { HiOutlineChevronDown, HiOutlineChevronRight, HiOutlineDownload, HiOutlinePlay, HiOutlinePlus, HiOutlineSave, HiOutlineSearch, HiOutlineX } from 'react-icons/hi'
import Button from '@/components/ui/Button'
import Checkbox from '@/components/ui/Checkbox'
import Input from '@/components/ui/Input'
import ActionDialog, { DialogField } from '@/components/v2/ActionDialog'
import { PageHead } from '@/components/v2/ListParts'
import { EmptyState, ErrorState, InlineError, SkeletonLines } from '@/components/v2/States'
import { Ltr } from '@/components/v2/Display'
import { Notice } from '@/views/phase5/parts'
import { Segmented } from '@/views/phase1/followUps/parts'
import useHashState, { hashCodec } from '@/utils/hooks/useHashState'
import type { HashSchema } from '@/utils/hooks/useHashState'
import { useV2Query } from '@/utils/v2/hooks'
import { formatCount } from '@/utils/v2/format'
import { sqlApi } from '@/services/v2/reportBuilderApi'
import type { DictTable, Dictionary, SavedSqlQuery, SqlAgg, SqlBuilderSpec, SqlOp, SqlResult } from '@/services/v2/reportBuilderApi'
import { describeBuilderError, pick } from '../shared'

type Tab = 'builder' | 'editor'
type Bottom = 'saved' | 'runs'
type HashState = { tab: Tab; bottom: Bottom; q: string | undefined }

const schema: HashSchema<HashState> = {
    tab: { key: 'tab', codec: hashCodec.oneOf(['builder', 'editor'] as const), default: 'builder' },
    bottom: { key: 'b', codec: hashCodec.oneOf(['saved', 'runs'] as const), default: 'saved' },
    q: { key: 'q', codec: hashCodec.text({ maxLength: 40 }), default: undefined },
}

const AGGS: SqlAgg[] = ['count', 'count_distinct', 'sum', 'avg', 'min', 'max']
const OPS: SqlOp[] = ['=', '!=', '>', '>=', '<', '<=', 'between', 'in', 'not_in', 'contains', 'starts_with', 'is_null', 'not_null']
const NUMERIC = ['money', 'number', 'int']
const PAGE = 100
const DRAFT_KEY = 'rb.sql.draft'

const readDraft = () => {
    try {
        return localStorage.getItem(DRAFT_KEY) || ''
    } catch {
        return ''
    }
}
const writeDraft = (v: string) => {
    try {
        localStorage.setItem(DRAFT_KEY, v)
    } catch {
        /* private window: the draft is not kept */
    }
}

const emptySpec = (table: string): SqlBuilderSpec => ({ table, joins: [], columns: [], filters: [], order_by: [], limit: 1000 })

const selectCls =
    'h-8 rounded-md border border-gray-300 bg-white px-2 text-[12.5px] dark:border-night-border dark:bg-night-card dark:text-gray-100'

/* ------------------------------------------------------------------ dictionary */
function DictionaryPanel({ dict, onPick }: { dict: Dictionary; onPick: (table: string, column?: string) => void }) {
    const { t, i18n } = useTranslation()
    const ar = (i18n.language || 'ar').startsWith('ar')
    const [q, setQ] = useState('')
    const [open, setOpen] = useState<Record<string, boolean>>({ cases: true })
    const needle = q.trim().toLocaleLowerCase()
    const hit = (s: string) => s.toLocaleLowerCase().includes(needle)
    return (
        <aside className="min-w-0 rounded-lg border border-gray-300 bg-white p-3 dark:border-night-border dark:bg-night-card" data-testid="rb-sql-dict">
            <div className="text-eyebrow mb-1">{t('rb.sql.dictionary')}</div>
            <p className="mb-2 text-[12px] text-gray-600">{t('rb.sql.dictionaryHint')}</p>
            <Input size="sm" prefix={<HiOutlineSearch className="text-gray-500" />} value={q} maxLength={60}
                   placeholder={String(t('rb.sql.searchDict'))} onChange={(e) => setQ(e.target.value)} data-testid="rb-sql-dict-search" />
            <div className="mt-2 max-h-[70vh] overflow-y-auto pe-1">
                {dict.tables.map((tb) => {
                    const cols = needle
                        ? tb.columns.filter((c) => [c.name, c.labels.en, c.labels.ar, c.description.en, c.description.ar].some(hit))
                        : tb.columns
                    const tableHit = needle && [tb.name, tb.labels.en, tb.labels.ar].some(hit)
                    if (needle && !cols.length && !tableHit) return null
                    const isOpen = !!needle || !!open[tb.name]
                    const joins = dict.joins.filter((j) => j.left === tb.name || j.right === tb.name)
                    return (
                        <div key={tb.name} className="mb-1 border-b border-gray-200 pb-1 dark:border-night-border" data-testid="rb-sql-dict-table" data-table={tb.name}>
                            <div className="flex items-center gap-1">
                                <button type="button" className="flex min-w-0 flex-1 items-center gap-1 py-1 text-start" aria-expanded={isOpen}
                                        onClick={() => setOpen({ ...open, [tb.name]: !open[tb.name] })}>
                                    {isOpen ? <HiOutlineChevronDown className="shrink-0" /> : <HiOutlineChevronRight className="shrink-0 rtl:rotate-180" />}
                                    <span className="truncate text-[13px] font-extrabold text-navy-600 dark:text-gray-100">{pick(tb.labels, ar)}</span>
                                    <Ltr className="ms-1 text-[11px] text-gray-500">{tb.name}</Ltr>
                                </button>
                                <button type="button" className="rounded border border-gray-300 px-1 text-[11px] text-gray-600 hover:border-azure-500 dark:border-night-border"
                                        title={String(t('rb.sql.useTable'))} aria-label={`${t('rb.sql.useTable')}: ${tb.name}`} onClick={() => onPick(tb.name)}>
                                    <HiOutlinePlus className="inline" />
                                </button>
                            </div>
                            {isOpen && (
                                <>
                                    <p className="mb-1 ps-5 text-[11.5px] text-gray-600">{pick(tb.description, ar)}</p>
                                    <ul className="ps-4">
                                        {cols.map((c) => (
                                            <li key={c.name}>
                                                <button type="button" onClick={() => onPick(tb.name, c.name)} data-testid="rb-sql-dict-col"
                                                        title={`${pick(c.description, !ar)}`}
                                                        className="w-full rounded px-1 py-0.5 text-start hover:bg-gray-50 dark:hover:bg-night-raised">
                                                    <span className="flex items-baseline gap-1.5">
                                                        <Ltr className="text-[12px] font-bold text-gray-800 dark:text-night-body">{c.name}</Ltr>
                                                        <span className="rounded-xs bg-gray-100 px-1 text-[10px] text-gray-600 dark:bg-night-raised">{t(`rb.type.${c.type}`, { defaultValue: c.type })}</span>
                                                        <span className="truncate text-[11.5px] text-navy-600 dark:text-gray-100">{pick(c.labels, ar)}</span>
                                                    </span>
                                                    <span className="block text-[11px] leading-snug text-gray-600">{pick(c.description, ar)}</span>
                                                </button>
                                            </li>
                                        ))}
                                    </ul>
                                    {joins.length > 0 && !needle && (
                                        <div className="mt-1 ps-5 text-[11px] text-gray-600">
                                            <span className="font-bold">{t('rb.sql.joinsTo')}</span>{' '}
                                            {joins.map((j, i) => (
                                                <Ltr key={i} className="me-2 inline-block">{j.left}.{j.left_column} = {j.right}.{j.right_column}</Ltr>
                                            ))}
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    )
                })}
            </div>
        </aside>
    )
}

/* ------------------------------------------------------------------ visual builder */
function Builder({ dict, spec, setSpec, onSql }: { dict: Dictionary; spec: SqlBuilderSpec; setSpec: (s: SqlBuilderSpec) => void; onSql: (sql: string, run: boolean) => void }) {
    const { t, i18n } = useTranslation()
    const ar = (i18n.language || 'ar').startsWith('ar')
    const [busy, setBusy] = useState(false)
    const [error, setError] = useState<unknown>(null)
    const [preview, setPreview] = useState('')
    const used = [spec.table, ...spec.joins.map((j) => j.table)]
    const tableOf = (name: string) => dict.tables.find((x) => x.name === name) as DictTable
    const colOptions = used.flatMap((tn) => tableOf(tn).columns.map((c) => ({ value: `${tn}.${c.name}`, label: `${tn}.${c.name} — ${pick(c.labels, ar)}`, type: c.type })))
    const typeOf = (ref: string) => colOptions.find((o) => o.value === ref)?.type || 'text'
    const joinOptions = dict.joins
        .filter((j) => (used.includes(j.left) && !used.includes(j.right)) || (used.includes(j.right) && !used.includes(j.left)))
        .map((j) => ({ ...j, table: used.includes(j.left) ? j.right : j.left }))
    const outNames = spec.columns.map((c) => (c.agg ? `${c.agg}(${c.table}.${c.column})` : `${c.table}.${c.column}`))
    const split = (ref: string) => {
        const [table, column] = ref.split('.')
        return { table, column }
    }

    const generate = async (run: boolean) => {
        setBusy(true)
        setError(null)
        try {
            const r = await sqlApi.build(spec)
            setPreview(r.sql)
            onSql(r.sql, run)
        } catch (e) {
            setError(e)
        } finally {
            setBusy(false)
        }
    }

    const section = (title: string, children: React.ReactNode, add?: React.ReactNode) => (
        <div className="mb-3 rounded-lg border border-gray-300 p-3 dark:border-night-border">
            <div className="mb-2 flex items-center justify-between gap-2">
                <span className="text-eyebrow">{title}</span>
                {add}
            </div>
            {children}
        </div>
    )
    const xBtn = (onClick: () => void, label: string) => (
        <button type="button" className="rounded p-1 text-gray-500 hover:text-danger" aria-label={label} onClick={onClick}><HiOutlineX /></button>
    )

    return (
        <div data-testid="rb-sql-builder">
            {section(t('rb.sql.b.table'),
                <select className={classNames(selectCls, 'w-full')} value={spec.table} data-testid="rb-sql-b-table"
                        onChange={(e) => setSpec(emptySpec(e.target.value))}>
                    {dict.tables.map((tb) => <option key={tb.name} value={tb.name}>{tb.name} — {pick(tb.labels, ar)}</option>)}
                </select>)}

            {section(t('rb.sql.b.joins'),
                <>
                    {spec.joins.map((j, i) => (
                        <div key={j.table} className="mb-1 flex flex-wrap items-center gap-2 text-[12.5px]">
                            <select className={selectCls} value={j.type} aria-label={String(t('rb.sql.b.joinType'))}
                                    onChange={(e) => setSpec({ ...spec, joins: spec.joins.map((x, k) => (k === i ? { ...x, type: e.target.value as 'left' | 'inner' } : x)) })}>
                                <option value="left">{t('rb.sql.b.left')}</option>
                                <option value="inner">{t('rb.sql.b.inner')}</option>
                            </select>
                            <Ltr className="font-bold">{j.table}</Ltr>
                            <Ltr className="text-gray-600">ON {j.on[0]}.{j.on[1]} = {j.on[2]}.{j.on[3]}</Ltr>
                            {xBtn(() => {
                                // drop the join and everything that used its table
                                const gone = spec.joins.slice(i).map((x) => x.table)
                                setSpec({ ...spec, joins: spec.joins.slice(0, i),
                                          columns: spec.columns.filter((c) => !gone.includes(c.table)),
                                          filters: spec.filters.filter((c) => !gone.includes(c.table)), order_by: [] })
                            }, String(t('rb.remove')))}
                        </div>
                    ))}
                    {!spec.joins.length && <div className="text-[12px] text-gray-500">{t('rb.sql.b.noJoins')}</div>}
                </>,
                joinOptions.length > 0 && spec.joins.length < 6 ? (
                    <select className={selectCls} value="" aria-label={String(t('rb.sql.b.addJoin'))} data-testid="rb-sql-b-addjoin"
                            onChange={(e) => {
                                const j = joinOptions[Number(e.target.value)]
                                if (j) setSpec({ ...spec, joins: [...spec.joins, { table: j.table, type: 'left', on: [j.left, j.left_column, j.right, j.right_column] }] })
                            }}>
                        <option value="">+ {t('rb.sql.b.addJoin')}</option>
                        {joinOptions.map((j, i) => <option key={i} value={i}>{j.table} ({j.left}.{j.left_column} = {j.right}.{j.right_column})</option>)}
                    </select>
                ) : null)}

            {section(t('rb.sql.b.columns'),
                <>
                    {spec.columns.map((c, i) => (
                        <div key={i} className="mb-1 flex flex-wrap items-center gap-2">
                            <select className={classNames(selectCls, 'min-w-0 flex-1')} value={`${c.table}.${c.column}`} aria-label={String(t('rb.sql.b.column'))}
                                    onChange={(e) => setSpec({ ...spec, columns: spec.columns.map((x, k) => (k === i ? { ...split(e.target.value), agg: null } : x)) })}>
                                {colOptions.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                            </select>
                            <select className={selectCls} value={c.agg || ''} aria-label={String(t('rb.sql.b.agg'))}
                                    onChange={(e) => setSpec({ ...spec, columns: spec.columns.map((x, k) => (k === i ? { ...x, agg: (e.target.value || null) as SqlAgg | null } : x)) })}>
                                <option value="">{t('rb.sql.b.noAgg')}</option>
                                {AGGS.filter((a) => (a === 'sum' || a === 'avg' ? NUMERIC.includes(typeOf(`${c.table}.${c.column}`)) : true))
                                    .map((a) => <option key={a} value={a}>{t(`rb.sql.agg.${a}`)}</option>)}
                            </select>
                            {xBtn(() => setSpec({ ...spec, columns: spec.columns.filter((_x, k) => k !== i), order_by: [] }), String(t('rb.remove')))}
                        </div>
                    ))}
                    {!spec.columns.length && <div className="text-[12px] text-gray-500">{t('rb.sql.b.noColumns')}</div>}
                    {spec.columns.some((c) => c.agg) && spec.columns.some((c) => !c.agg) && (
                        <div className="mt-1 text-[11.5px] text-gray-600">{t('rb.sql.b.groupedBy', { cols: spec.columns.filter((c) => !c.agg).map((c) => `${c.table}.${c.column}`).join(', ') })}</div>
                    )}
                </>,
                <Button size="xs" icon={<HiOutlinePlus />} data-testid="rb-sql-b-addcol"
                        onClick={() => setSpec({ ...spec, columns: [...spec.columns, { ...split(colOptions[0].value), agg: null }] })}>
                    {t('rb.add')}
                </Button>)}

            {section(t('rb.sql.b.filters'),
                <>
                    {spec.filters.map((f, i) => {
                        const ty = typeOf(`${f.table}.${f.column}`)
                        const setF = (patch: Partial<typeof f>) => setSpec({ ...spec, filters: spec.filters.map((x, k) => (k === i ? { ...x, ...patch } : x)) })
                        const inputType = ty === 'date' ? 'date' : NUMERIC.includes(ty) ? 'number' : 'text'
                        return (
                            <div key={i} className="mb-1 flex flex-wrap items-center gap-2">
                                <select className={classNames(selectCls, 'min-w-0 flex-1')} value={`${f.table}.${f.column}`} aria-label={String(t('rb.sql.b.column'))}
                                        onChange={(e) => setF({ ...split(e.target.value), value: undefined })}>
                                    {colOptions.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                                </select>
                                <select className={selectCls} value={f.op} aria-label={String(t('rb.sql.b.op'))}
                                        onChange={(e) => setF({ op: e.target.value as SqlOp, value: e.target.value === 'between' ? ['', ''] : undefined })}>
                                    {OPS.map((o) => <option key={o} value={o}>{t(`rb.sql.op.${o}`, { defaultValue: o })}</option>)}
                                </select>
                                {f.op === 'between' ? (
                                    [0, 1].map((k) => (
                                        <Input key={k} size="sm" className="w-36" type={inputType} value={String((f.value as string[])?.[k] ?? '')}
                                               aria-label={String(t(k ? 'rb.bi.to' : 'rb.bi.from'))}
                                               onChange={(e) => { const v = [...((f.value as string[]) || ['', ''])]; v[k] = e.target.value; setF({ value: v }) }} />
                                    ))
                                ) : f.op === 'in' || f.op === 'not_in' ? (
                                    <Input size="sm" className="w-56" placeholder={String(t('rb.sql.b.listHint'))}
                                           value={Array.isArray(f.value) ? (f.value as string[]).join(', ') : ''}
                                           onChange={(e) => setF({ value: e.target.value.split(',').map((x) => x.trim()).filter(Boolean) })} />
                                ) : f.op === 'is_null' || f.op === 'not_null' ? null : ty === 'bool' ? (
                                    <select className={selectCls} value={String(f.value ?? '')} aria-label={String(t('rb.bi.value'))} onChange={(e) => setF({ value: e.target.value })}>
                                        <option value="">—</option>
                                        <option value="true">{t('rb.yes')}</option>
                                        <option value="false">{t('rb.no')}</option>
                                    </select>
                                ) : (
                                    <Input size="sm" className="w-48" type={inputType} value={String(f.value ?? '')} aria-label={String(t('rb.bi.value'))}
                                           onChange={(e) => setF({ value: e.target.value })} />
                                )}
                                {xBtn(() => setSpec({ ...spec, filters: spec.filters.filter((_x, k) => k !== i) }), String(t('rb.remove')))}
                            </div>
                        )
                    })}
                    {!spec.filters.length && <div className="text-[12px] text-gray-500">{t('rb.sql.b.noFilters')}</div>}
                </>,
                <Button size="xs" icon={<HiOutlinePlus />}
                        onClick={() => setSpec({ ...spec, filters: [...spec.filters, { ...split(colOptions[0].value), op: '=', value: '' }] })}>
                    {t('rb.add')}
                </Button>)}

            {section(t('rb.sql.b.order'),
                <div className="flex flex-wrap items-center gap-2">
                    {spec.order_by.map((o, i) => (
                        <span key={i} className="inline-flex items-center gap-1">
                            <select className={selectCls} value={o.index} aria-label={String(t('rb.sql.b.order'))}
                                    onChange={(e) => setSpec({ ...spec, order_by: spec.order_by.map((x, k) => (k === i ? { ...x, index: Number(e.target.value) } : x)) })}>
                                {outNames.map((n, k) => <option key={k} value={k}>{n}</option>)}
                            </select>
                            <select className={selectCls} value={o.dir} aria-label={String(t('rb.sql.b.dir'))}
                                    onChange={(e) => setSpec({ ...spec, order_by: spec.order_by.map((x, k) => (k === i ? { ...x, dir: e.target.value as 'asc' | 'desc' } : x)) })}>
                                <option value="asc">{t('rb.sql.b.asc')}</option>
                                <option value="desc">{t('rb.sql.b.desc')}</option>
                            </select>
                            {xBtn(() => setSpec({ ...spec, order_by: spec.order_by.filter((_x, k) => k !== i) }), String(t('rb.remove')))}
                        </span>
                    ))}
                    {outNames.length > 0 && spec.order_by.length < 5 && (
                        <Button size="xs" icon={<HiOutlinePlus />} onClick={() => setSpec({ ...spec, order_by: [...spec.order_by, { index: 0, dir: 'asc' }] })}>{t('rb.add')}</Button>
                    )}
                    <label className="ms-auto flex items-center gap-2 text-[12.5px]">
                        {t('rb.sql.b.limit')}
                        <Input size="sm" className="w-28" type="number" min={1} max={10000} value={String(spec.limit)}
                               onChange={(e) => setSpec({ ...spec, limit: Math.max(1, Math.min(10000, Number(e.target.value) || 1)) })} />
                    </label>
                </div>)}

            <div className="flex flex-wrap items-center gap-2">
                <Button size="sm" variant="solid" icon={<HiOutlinePlay />} loading={busy} disabled={!spec.columns.length} onClick={() => generate(true)} data-testid="rb-sql-b-run">
                    {t('rb.sql.b.buildRun')}
                </Button>
                <Button size="sm" disabled={!spec.columns.length || busy} onClick={() => generate(false)} data-testid="rb-sql-b-open">
                    {t('rb.sql.b.openEditor')}
                </Button>
            </div>
            {error ? <InlineError error={error} describe={describeBuilderError} /> : null}
            {preview && (
                <pre dir="ltr" className="mt-3 overflow-x-auto rounded-md border border-gray-300 bg-gray-50 p-3 text-[12px] leading-relaxed dark:border-night-border dark:bg-night-raised" data-testid="rb-sql-b-preview">
                    {preview}
                </pre>
            )}
        </div>
    )
}

/* ------------------------------------------------------------------ editor */
function SqlEditor({ value, onChange, onRun }: { value: string; onChange: (v: string) => void; onRun: () => void }) {
    const { t } = useTranslation()
    const gutter = useRef<HTMLDivElement>(null)
    const lines = Math.max(value.split('\n').length, 12)
    return (
        <div dir="ltr" className="flex overflow-hidden rounded-md border border-gray-300 bg-white font-mono text-[13px] dark:border-night-border dark:bg-night-card">
            <div ref={gutter} aria-hidden className="select-none overflow-hidden bg-gray-50 px-2 py-2 text-end text-gray-400 dark:bg-night-raised" style={{ lineHeight: '20px' }}>
                {Array.from({ length: lines }, (_, i) => <div key={i}>{i + 1}</div>)}
            </div>
            <textarea
                value={value}
                spellCheck={false}
                aria-label={String(t('rb.sql.editor'))}
                data-testid="rb-sql-editor"
                placeholder="SELECT contract_name, sum(amount) AS collected&#10;FROM payments&#10;WHERE counts_as_collected&#10;GROUP BY contract_name"
                className="min-h-[280px] w-full resize-y bg-transparent px-3 py-2 outline-none"
                style={{ lineHeight: '20px', tabSize: 2 }}
                onScroll={(e) => { if (gutter.current) gutter.current.scrollTop = (e.target as HTMLTextAreaElement).scrollTop }}
                onChange={(e) => onChange(e.target.value)}
                onKeyDown={(e) => {
                    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                        e.preventDefault()
                        onRun()
                    } else if (e.key === 'Tab' && !e.shiftKey) {
                        e.preventDefault()
                        const el = e.currentTarget
                        const { selectionStart: a, selectionEnd: b } = el
                        onChange(value.slice(0, a) + '  ' + value.slice(b))
                        requestAnimationFrame(() => el.setSelectionRange(a + 2, a + 2))
                    }
                }}
            />
        </div>
    )
}

/* ------------------------------------------------------------------ results */
function ResultGrid({ result }: { result: SqlResult }) {
    const { t } = useTranslation()
    const [page, setPage] = useState(1)
    useEffect(() => setPage(1), [result])
    const pages = Math.max(1, Math.ceil(result.rows.length / PAGE))
    const rows = result.rows.slice((page - 1) * PAGE, page * PAGE)
    if (!result.columns.length) return null
    return (
        <div data-testid="rb-sql-result">
            <div className="max-h-[520px] overflow-auto rounded-lg border border-gray-300 dark:border-night-border">
                <table dir="ltr" className="min-w-full border-collapse text-[12.5px]">
                    <thead className="sticky top-0 bg-gray-50 dark:bg-night-raised">
                        <tr>
                            <th className="border-b border-e border-gray-300 px-2 py-2 text-end text-[11px] text-gray-500 dark:border-night-border">#</th>
                            {result.columns.map((c, i) => (
                                <th key={i} className="whitespace-nowrap border-b border-e border-gray-300 px-3 py-2 text-start dark:border-night-border">
                                    <span className="font-extrabold text-navy-600 dark:text-gray-100">{c.name}</span>
                                    <span className="ms-1 text-[10.5px] font-normal text-gray-500">{t(`rb.type.${c.type}`, { defaultValue: c.type })}</span>
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody>
                        {rows.map((r, ri) => (
                            <tr key={ri} className="hover:bg-gray-50 dark:hover:bg-night-raised">
                                <td className="border-b border-e border-gray-200 px-2 py-1 text-end text-[11px] text-gray-500 dark:border-night-border">{(page - 1) * PAGE + ri + 1}</td>
                                {r.map((v, ci) => (
                                    <td key={ci} className={classNames('max-w-[420px] truncate whitespace-nowrap border-b border-e border-gray-200 px-3 py-1 dark:border-night-border',
                                        NUMERIC.includes(result.columns[ci]?.type) && 'text-end tabular-nums')} title={v === null ? '' : String(v)}>
                                        {v === null ? <span className="text-gray-400">NULL</span> : typeof v === 'boolean' ? String(v) : String(v)}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            {pages > 1 && (
                <div className="mt-2 flex items-center justify-end gap-2 text-[12.5px]">
                    <Button size="xs" disabled={page <= 1} onClick={() => setPage(page - 1)}>{t('rb.prev')}</Button>
                    <span className="tabular-nums">{t('rb.pageOf', { page, pages })}</span>
                    <Button size="xs" disabled={page >= pages} onClick={() => setPage(page + 1)}>{t('rb.next')}</Button>
                </div>
            )}
        </div>
    )
}

/* ------------------------------------------------------------------ page */
const SqlPage = () => {
    const { t, i18n } = useTranslation()
    const ar = (i18n.language || 'ar').startsWith('ar')
    const { state, setState } = useHashState(schema)
    const dict = useV2Query((signal) => sqlApi.dictionary(signal), [])
    const status = useV2Query((signal) => sqlApi.status(signal), [])
    const saved = useV2Query((signal) => sqlApi.queries(signal), [])
    const runs = useV2Query(state.bottom === 'runs' ? (signal) => sqlApi.runs({ kind: undefined }, signal) : null, [state.bottom])
    const [sql, setSqlState] = useState(readDraft)
    const [spec, setSpec] = useState<SqlBuilderSpec>(emptySpec('payments'))
    const [result, setResult] = useState<SqlResult | null>(null)
    const [running, setRunning] = useState(false)
    const [exporting, setExporting] = useState(false)
    const [error, setError] = useState<unknown>(null)
    const [saveOpen, setSaveOpen] = useState(false)
    const [saveName, setSaveName] = useState('')
    const [saveShared, setSaveShared] = useState(false)
    const [listError, setListError] = useState<unknown>(null)
    const loaded = (saved.data?.items || []).find((q) => q.id === state.q)

    const setSql = (v: string) => {
        setSqlState(v)
        writeDraft(v)
    }

    const run = async (text?: string) => {
        const q = (text ?? sql).trim()
        if (!q) return
        setRunning(true)
        setError(null)
        try {
            setResult(await sqlApi.run(q))
            if (state.bottom === 'runs') runs.reload()
        } catch (e) {
            setError(e)
            setResult(null)
        } finally {
            setRunning(false)
        }
    }

    const doExport = async () => {
        setExporting(true)
        setError(null)
        try {
            await sqlApi.exportXlsx(sql.trim(), ar ? 'ar' : 'en')
        } catch (e) {
            setError(e)
        } finally {
            setExporting(false)
        }
    }

    const pickFromDict = (table: string, column?: string) => {
        if (state.tab === 'editor') {
            setSql(sql + (sql && !/\s$/.test(sql) ? ' ' : '') + (column ? `${table}.${column}` : table))
            return
        }
        if (!column) {
            setSpec(emptySpec(table))
            return
        }
        const used = [spec.table, ...spec.joins.map((j) => j.table)]
        if (used.includes(table)) setSpec({ ...spec, columns: [...spec.columns, { table, column, agg: null }] })
    }

    const loadQuery = (q: SavedSqlQuery) => {
        setSql(q.sql_text)
        if (q.builder) setSpec(q.builder)
        setState({ q: q.id, tab: 'editor' })
        setResult(null)
    }

    const removeQuery = async (q: SavedSqlQuery) => {
        if (!window.confirm(String(t('rb.bi.confirmDelete', { name: q.name })))) return
        setListError(null)
        try {
            await sqlApi.remove(q.id)
            if (state.q === q.id) setState({ q: undefined })
            saved.reload()
        } catch (e) {
            setListError(e)
        }
    }

    const updateLoaded = async () => {
        if (!loaded) return
        setListError(null)
        try {
            await sqlApi.update(loaded.id, { sql_text: sql, builder: spec, expected_revision: loaded.revision })
            saved.reload()
        } catch (e) {
            setListError(e)
        }
    }

    const tableCount = useMemo(() => dict.data?.tables.length || 0, [dict.data])

    if (dict.loading && !dict.data) return <SkeletonLines rows={10} />
    if (dict.error && !dict.data) return <ErrorState error={dict.error} onRetry={dict.reload} describe={describeBuilderError} />
    if (!dict.data) return null
    if (status.error) return <ErrorState error={status.error} onRetry={status.reload} describe={describeBuilderError} />
    const notConfigured = status.data && !status.data.configured

    return (
        <div data-testid="rb-sql">
            <PageHead title={t('rb.sql.title')} subtitle={t('rb.sql.subtitle', { n: tableCount })} />
            <Notice tone="info" className="mb-3">{t('rb.sql.safetyNote', { rows: formatCount(status.data?.max_rows ?? 10000), s: Math.round((status.data?.timeout_ms ?? 15000) / 1000) })}</Notice>
            {notConfigured && <Notice tone="warning" className="mb-3" testId="rb-sql-not-configured">{t('rb.err.sql_runner_not_configured')}</Notice>}

            <div className="grid grid-cols-1 gap-4 xl:grid-cols-[340px_minmax(0,1fr)]">
                <DictionaryPanel dict={dict.data} onPick={pickFromDict} />
                <div className="min-w-0">
                    <div className="mb-3 flex flex-wrap items-center gap-2">
                        <Segmented<Tab> value={state.tab} label={String(t('rb.sql.mode'))} testId="rb-sql-tabs"
                            options={[{ value: 'builder', label: t('rb.sql.tabBuilder') }, { value: 'editor', label: t('rb.sql.tabEditor') }]}
                            onChange={(tab) => setState({ tab })} />
                        {loaded && <span className="text-[12px] text-gray-600">{t('rb.bi.loaded', { name: loaded.name })}</span>}
                    </div>

                    <div className="rounded-lg border border-gray-300 bg-white p-4 dark:border-night-border dark:bg-night-card">
                        {state.tab === 'builder' ? (
                            <Builder dict={dict.data} spec={spec} setSpec={setSpec}
                                     onSql={(text, doRun) => { setSql(text); if (doRun) run(text); else setState({ tab: 'editor' }) }} />
                        ) : (
                            <>
                                <SqlEditor value={sql} onChange={setSql} onRun={() => run()} />
                                <div className="mt-3 flex flex-wrap items-center gap-2">
                                    <Button size="sm" variant="solid" icon={<HiOutlinePlay />} loading={running} disabled={!sql.trim() || !!notConfigured} onClick={() => run()} data-testid="rb-sql-run">
                                        {t('rb.run')} <span className="ms-1 text-[11px] opacity-75">Ctrl+Enter</span>
                                    </Button>
                                    <Button size="sm" icon={<HiOutlineDownload />} loading={exporting} disabled={!sql.trim() || !!notConfigured} onClick={doExport} data-testid="rb-sql-export">
                                        {t('rb.exportExcel')}
                                    </Button>
                                    {loaded?.mine && <Button size="sm" onClick={updateLoaded}>{t('rb.bi.saveChanges')}</Button>}
                                    <Button size="sm" icon={<HiOutlineSave />} disabled={!sql.trim()} data-testid="rb-sql-save"
                                            onClick={() => { setSaveName(''); setSaveShared(false); setSaveOpen(true) }}>
                                        {t('rb.bi.saveAs')}
                                    </Button>
                                </div>
                            </>
                        )}
                    </div>

                    <div className="mt-4">
                        {error ? <InlineError error={error} describe={describeBuilderError} /> : null}
                        {running && !result ? <SkeletonLines rows={6} /> : null}
                        {result && (
                            <>
                                <div className="mb-2 flex flex-wrap items-center gap-3 text-[12.5px] text-gray-600" data-testid="rb-sql-meta">
                                    <span className="tabular-nums">{t('rb.sql.meta', { rows: formatCount(result.row_count), ms: result.ms })}</span>
                                    {state.tab === 'builder' && (
                                        <Button size="xs" icon={<HiOutlineDownload />} loading={exporting} onClick={doExport}>{t('rb.exportExcel')}</Button>
                                    )}
                                </div>
                                {result.truncated && <Notice tone="warning" className="mb-2">{t('rb.sql.truncated', { n: formatCount(result.limit) })}</Notice>}
                                {result.row_count === 0 ? <EmptyState title={t('rb.sql.noRows')} /> : <ResultGrid result={result} />}
                            </>
                        )}
                    </div>

                    {/* ---------- saved queries / run history */}
                    <div className="mt-6 rounded-lg border border-gray-300 bg-white p-4 dark:border-night-border dark:bg-night-card">
                        <Segmented<Bottom> value={state.bottom} label={String(t('rb.sql.lists'))} testId="rb-sql-bottom"
                            options={[{ value: 'saved', label: t('rb.sql.savedQueries') }, { value: 'runs', label: t('rb.sql.recentRuns') }]}
                            onChange={(bottom) => setState({ bottom })} />
                        <div className="mt-3">
                            {listError ? <InlineError error={listError} describe={describeBuilderError} onReload={saved.reload} /> : null}
                            {state.bottom === 'saved' ? (
                                (saved.data?.items || []).length === 0 ? (
                                    <div className="text-[12.5px] text-gray-500">{t('rb.bi.noSaved')}</div>
                                ) : (
                                    <ul className="divide-y divide-gray-200 dark:divide-night-border" data-testid="rb-sql-saved">
                                        {(saved.data?.items || []).map((q) => (
                                            <li key={q.id} className="flex items-center gap-2 py-1.5 text-[12.5px]">
                                                <button type="button" className="min-w-0 truncate text-start font-bold text-azure-600 hover:underline" onClick={() => loadQuery(q)}>{q.name}</button>
                                                {q.shared && <span className="rounded-xs border border-gray-300 px-1 text-[10px] text-gray-600 dark:border-night-border">{t('rb.shared')}</span>}
                                                {!q.mine && <span className="text-[11px] text-gray-500">{t('rb.sharedBy', { name: q.owner_name || '—' })}</span>}
                                                <Ltr className="ms-auto truncate text-[11px] text-gray-500">{q.sql_text.replace(/\s+/g, ' ').slice(0, 80)}</Ltr>
                                                {q.mine && (
                                                    <button type="button" className="rounded p-1 text-gray-500 hover:text-danger" aria-label={String(t('rb.bi.remove', { name: q.name }))} onClick={() => removeQuery(q)}>
                                                        <HiOutlineX />
                                                    </button>
                                                )}
                                            </li>
                                        ))}
                                    </ul>
                                )
                            ) : runs.loading && !runs.data ? (
                                <SkeletonLines rows={4} />
                            ) : runs.error ? (
                                <InlineError error={runs.error} describe={describeBuilderError} />
                            ) : (
                                <div className="overflow-x-auto">
                                    <table className="min-w-full text-[12.5px]" data-testid="rb-sql-runs">
                                        <thead>
                                            <tr className="text-start text-gray-600">
                                                <th className="px-2 py-1 text-start">{t('rb.runs.when')}</th>
                                                <th className="px-2 py-1 text-start">{t('rb.runs.kind')}</th>
                                                <th className="px-2 py-1 text-start">{t('rb.runs.outcome')}</th>
                                                <th className="px-2 py-1 text-end">{t('rb.runs.rows')}</th>
                                                <th className="px-2 py-1 text-end">ms</th>
                                                <th className="px-2 py-1 text-start">{t('rb.runs.what')}</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {(runs.data?.items || []).map((r) => (
                                                <tr key={r.id} className="border-t border-gray-200 dark:border-night-border">
                                                    <td className="whitespace-nowrap px-2 py-1"><Ltr>{new Date(r.created_at).toLocaleString(ar ? 'ar-SA-u-nu-latn' : 'en-GB', { timeZone: 'Asia/Riyadh' })}</Ltr></td>
                                                    <td className="px-2 py-1">{t(`rb.runs.kinds.${r.kind}`)}</td>
                                                    <td className={classNames('px-2 py-1 font-bold', r.outcome === 'ok' ? 'text-success' : 'text-danger')}>
                                                        {t(`rb.runs.outcomes.${r.outcome}`)}{r.error_code ? ` (${r.error_code})` : ''}
                                                    </td>
                                                    <td className="px-2 py-1 text-end tabular-nums">{r.row_count ?? '—'}</td>
                                                    <td className="px-2 py-1 text-end tabular-nums">{r.duration_ms ?? '—'}</td>
                                                    <td className="max-w-[420px] truncate px-2 py-1">
                                                        {r.sql_text ? (
                                                            <button type="button" className="truncate text-start text-azure-600 hover:underline" dir="ltr"
                                                                    onClick={() => { setSql(r.sql_text || ''); setState({ tab: 'editor' }) }}>
                                                                {r.sql_text.replace(/\s+/g, ' ').slice(0, 100)}
                                                            </button>
                                                        ) : r.dataset ? t('rb.runs.dataset', { ds: r.dataset }) : '—'}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <ActionDialog
                isOpen={saveOpen}
                title={t('rb.sql.saveTitle')}
                onClose={() => setSaveOpen(false)}
                canSubmit={saveName.trim().length > 0 && saveName.trim().length <= 120}
                confirmLabel={t('rb.save')}
                describeError={describeBuilderError}
                testId="rb-sql-save-dialog"
                onSubmit={async (key) => {
                    const r = await sqlApi.save({ name: saveName.trim(), sql_text: sql, builder: spec, shared: saveShared }, key)
                    setState({ q: r.id })
                    saved.reload()
                }}
            >
                <DialogField label={t('rb.name')} required>
                    <Input size="sm" value={saveName} maxLength={120} onChange={(e) => setSaveName(e.target.value)} data-testid="rb-sql-save-name" />
                </DialogField>
                <Checkbox checked={saveShared} onChange={(c: boolean) => setSaveShared(c)}>{t('rb.shareHintSql')}</Checkbox>
            </ActionDialog>
        </div>
    )
}

export default SqlPage
